if(identity.server){try{state=await commerceRequest();}catch(error){stateLoadError=error.message;state={products:[],suppliers:[],orders:[],payouts:[],cart:[],favorites:[],customer:{addresses:[]}};}}
else{state=readState(scopedStorage);addWorkspaceDemo(state,brands);try{persist(state,scopedStorage);}catch{}}
async function command(action,body){const response=await commerceRequest(action,body);state=response.state;return response.result;}
const app=document.querySelector('#app'),modal=document.querySelector('#modal');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const returnNotice='<div class="purchase-policy"><strong>Обмен и возврат</strong><p>Обмен не предусмотрен. Возврат — в случаях и порядке, предусмотренных законом.</p><a class="text-link" href="#/contact">Уточнить условия у магазина ↗</a></div>';
const paths={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',user:'<circle cx="12" cy="7" r="3.5"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>',bag:'<path d="M5 7h14l1 15H4L5 7Z"/><path d="M8 8V5a4 4 0 0 1 8 0v3"/>',heart:'<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>'};
const icon=n=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[n]||''}</svg>`;
// Original supplied logo; CSS frames the monogram without altering the asset.
let brandCounter=0;
const brand=()=>{const id='brand-ink-'+(++brandCounter);const defs='<defs><filter id="'+id+'" color-interpolation-filters="sRGB"><feColorMatrix type="matrix" values="0 0 0 0 .208 0 0 0 0 .161 0 0 0 0 .098 -.5 -.5 -.5 0 1.25"/></filter></defs>';return '<a class="brand original-brand" href="#/" aria-label="Vera Privé — главная"><svg class="logo-monogram" viewBox="375 50 530 540" aria-hidden="true">'+defs+'<image filter="url(#'+id+')" href="/assets/vera-prive-logo.jpg" width="1280" height="853"/></svg><svg class="logo-wordmark" viewBox="220 585 850 170" aria-hidden="true"><defs><filter id="'+id+'-word" color-interpolation-filters="sRGB"><feColorMatrix type="matrix" values="0 0 0 0 .208 0 0 0 0 .161 0 0 0 0 .098 -.5 -.5 -.5 0 1.25"/></filter></defs><image filter="url(#'+id+'-word)" href="/assets/vera-prive-logo.jpg" width="1280" height="853"/></svg></a>';};
const route=()=>{try {const r=decodeURIComponent(location.hash.slice(1)||'/');return r.startsWith('/catalog/')&&!allCategories.includes(r.slice(9))?'/not-found':r;}catch{return '/not-found';}};
const supplierName=id=>state.suppliers.find(s=>s.id===id)?.name||'Поставщик';
const date=s=>new Date(s).toLocaleDateString('ru-RU');
const status=o=>`<span class="badge ${o.status}">${{pending:'Новая заявка',sold:'Продажа подтверждена',cancelled:'Отменён'}[o.status]}</span>`;
const notice=identity.server?'<div class="notice">Данные сохраняются в магазине. Продажи подтверждает администратор; онлайн-оплата пока не подключена.</div>':'<div class="notice">Демонстрационный кабинет · данные сохраняются в этом браузере. Переключение ролей — для просмотра интерфейса, без авторизации.</div>';
for(const p of state.payouts)if(!p.id)p.id='pay-'+crypto.randomUUID();
let savedState=structuredClone(state);
let workspaceQuery='',supplierQuery='';
function save(){if(identity.server)return;try{persist(state,scopedStorage);savedState=structuredClone(state);}catch{state=structuredClone(savedState);throw Error('Не удалось сохранить: хранилище браузера заполнено. Попробуйте фото меньшего размера.');}}
let toastTimer;function toast(msg){const t=document.querySelector('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),4000);}
function favoritesPage(){const products=state.products.filter(p=>!p.archivedAt&&state.favorites.includes(p.id));return '<div class="wrap"><div class="page-head"><p class="eyebrow">ВАШ ЛИЧНЫЙ ВЫБОР</p><h1>Избранное</h1><p class="small muted">'+products.length+' вещей, к которым хочется вернуться</p></div>'+(products.length?'<div class="product-grid">'+products.map(productCard).join('')+'</div>':empty('Сохраните то, что нравится','Нажмите сердечко на карточке — и вещь появится здесь.'))+'</div>';}
function flyHeart(rect){
  toast('Добавлено в избранное');
  const target=document.querySelector('.favorites-destination');
  if(!target||matchMedia('(prefers-reduced-motion: reduce)').matches)return;
  const end=target.getBoundingClientRect(),heart=document.createElement('span');
  heart.className='flying-heart';heart.setAttribute('aria-hidden','true');heart.innerHTML=icon('heart');
  const x=rect.left+rect.width/2-12,y=rect.top+rect.height/2-12,dx=end.left+end.width/2-12-x,dy=end.top+end.height/2-12-y;
  heart.style.left=x+'px';heart.style.top=y+'px';document.body.append(heart);
  heart.animate([{transform:'translate(0,0) scale(1)',opacity:1},{transform:'translate('+dx*.45+'px,'+(dy*.55-45)+'px) scale(1.15)',opacity:1},{transform:'translate('+dx+'px,'+dy+'px) scale(.7)',opacity:.35}],{duration:HEART_FLIGHT_MS,easing:'cubic-bezier(.35,0,.25,1)'}).finished.then(()=>{heart.remove();if(target.isConnected)target.animate([{transform:'scale(1)'},{transform:'scale(1.12)'},{transform:'scale(1)'}],{duration:350});}).catch(()=>heart.remove());
}
function header(){const count=state.cart.reduce((a,r)=>a+r.quantity,0);return `<div class="demo-bar">${identity.server?'VERA PRIVÉ · Тестовый запуск · Онлайн-оплата пока недоступна':'ПРЕДПРОСМОТР МАГАЗИНА · Демонстрационные товары, без реальной оплаты'}</div><div class="header-slot"><header class="header wrap"><div class="header-main">${menuButton()}${brand()}<div class="header-actions"><a class="icon-btn" href="#/search" aria-label="Поиск">${icon('search')}</a><a class="icon-btn favorites-destination" href="#/favorites" aria-label="Избранное">${icon("heart")}${state.favorites.length?`<span class="count">${state.favorites.length}</span>`:""}</a><a class="icon-btn" href="#${accountHome(identity.user)}" aria-label="Личный кабинет">${icon('user')}</a><a class="icon-btn" href="#/cart" aria-label="Корзина, ${count} товаров">${icon('bag')}${count?`<span class="count">${count}</span>`:''}</a></div></div></header></div>`;}
function footer(){return `<footer><div class="wrap">${socialView()}<p class="small legal-links"><a href="/legal/privacy.html">Конфиденциальность и персональные данные</a> · <a href="/legal/consent.html">Согласие на обработку данных</a> · <a href="#/cookies">Cookie</a></p><p class="small">ИП Примерова Мария Ивановна · ИНН 000000000000 · ОГРНИП 000000000000000 · <a href="mailto:info@shop.example.com">info@shop.example.com</a> · <a href="tel:+70000000000">+7 (000) 000-00-00</a> · <a href="https://t.me/example_shop_contact" target="_blank" rel="noopener noreferrer">Telegram @example_shop_contact</a></p><div class="footer-bottom"><span>© ${new Date().getFullYear()} Vera Privé · С заботой о вашем стиле</span><div class="role-links">${identity.server?(identity.user?.role==='admin'?'<a href="#/admin">Управление магазином ↗</a>':identity.user?.role==='supplier'?'<a href="#/supplier">Кабинет поставщика ↗</a>':''):'<span>Демо-кабинеты:</span><a href="#/admin">Администратор ↗</a><a href="#/supplier">Поставщик ↗</a>'}</div></div></div></footer>`;}
function productCard(p){return `<article class="product" data-product-link="${p.id}"><div class="product-image">${gallery(p,esc)}${p.newWithTags?'<span class="photo-condition">Новое с биркой</span>':''}${p.demo?'':`<button class="favorite ${state.favorites.includes(p.id)?'active':''}" data-action="favorite" data-id="${p.id}" aria-label="${state.favorites.includes(p.id)?'Убрать из избранного':'В избранное'}" aria-pressed="${state.favorites.includes(p.id)}">${icon('heart')}</button>`}</div><div class="product-meta"><div><div class="product-category">${esc(findBrand(brands,p.brandId)?.name||p.brandName||p.category)}</div><a href="#/product/${p.id}" class="product-name">${esc(p.name)}</a><div class="product-color">${esc(p.color)}</div></div><div class="product-price">${p.demo?'Тест · не продаётся':priceMarkup(p)}</div></div></article>`;}
const empty=(title,text,link='/catalog',label='Перейти в каталог')=>`<div class="empty"><h3>${title}</h3><p class="muted small">${text}</p><a class="btn" href="#${link}">${label} →</a></div>`;
let homeLimit=12;
let categoryScope=null;
const homeRanks=new Map();
function homeProducts(){return filterProducts(catalogProducts(),{search,audience:catalogFilters.audience,brandCatalog:brands}).map(p=>{if(!homeRanks.has(p.id))homeRanks.set(p.id,Math.random());return p;}).sort((a,b)=>homeRanks.get(a.id)-homeRanks.get(b.id));}
function homeFeed(){const rows=homeProducts();return `<section class="section home-feed" id="home-finds"><div class="section-head"><div><p class="eyebrow">ВЕЩИ С ХАРАКТЕРОМ</p><h2>${search?'Результаты поиска':'Откройте для себя'}</h2><p class="small muted">${search?`По запросу «${esc(search)}» найдено: ${rows.length}`:'Новые и винтажные находки вперемешку'}</p></div></div>${audienceTabs()}${rows.length?`<div class="product-grid">${rows.slice(0,homeLimit).map(productCard).join('')}</div>`:'<p class="muted">В этом разделе ничего не найдено. Выберите «Все» или измените поисковый запрос.</p>'}<div class="home-more"><a class="btn wide" href="#/search">Смотреть ещё</a></div></section>`;}
function home(){return `<section class="hero"><div class="hero-copy"><span class="eyebrow resale-label">VERA PRIVÉ · RESALE SHOP</span><h1>Искусство<br>быть собой</h1><p>Магазин люксового ресейла: одежда, сумки и аксессуары любимых брендов.</p><div class="authenticity-note"><span aria-hidden="true">✧</span> 100% оригинал</div></div><div class="hero-image"><img src="${images.hero}" alt="Городской образ и подбор одежды" fetchpriority="high"><span class="hero-caption">Vera Privé · Selected with care</span></div></section><div class="wrap">${homeFeed()}<section class="editorial"><div><p class="eyebrow">ФИЛОСОФИЯ VERA PRIVÉ</p><h2>Меньше случайного.<br>Больше вашего.</h2></div><div><p>Мы верим в гардероб, который отражает вас. В спокойные оттенки, продуманные сочетания и вещи, к которым хочется возвращаться.</p><a href="#/about" class="text-link" style="display:inline-block;margin-top:22px">Познакомиться с Vera Privé ⟶</a></div></section><div class="service-row"><div><h4>Осознанный выбор</h4><p>Фотографии, описание и размеры каждой вещи</p></div><div><h4>Ваше личное пространство</h4><p>Избранное и история заказов в одном месте</p></div><div><h4>Рядом, когда нужно</h4><p><a href="#/contact">Свяжитесь с нами по вопросам подбора</a></p></div></div></div>`;}
function shopSearch(){return `<form id="search-form" class="searchbox shop-search">${icon('search')}<input name="search" aria-label="Поиск товаров" placeholder="Найти бренд или вещь" autocomplete="off" value="${esc(search)}"><button class="btn" type="submit">Найти</button></form>`;}
const audienceLabels={women:'Женское',men:'Мужское',unisex:'Унисекс',kids:'Детское'};
function audienceTabs(){return `<div class="audience-tabs" aria-label="Для кого"><button type="button" data-action="audience" data-audience="" aria-pressed="${!catalogFilters.audience}">Все</button>${Object.entries(audienceLabels).filter(([key])=>key!=='unisex').map(([key,label])=>`<button type="button" data-action="audience" data-audience="${key}" aria-pressed="${catalogFilters.audience===key}">${label}</button>`).join('')}</div>`;}
function conditionTabs(){return `<div class="condition-tabs" aria-label="Состояние вещей">${[['all','Все вещи'],['new','Новое с биркой'],['used','Б/у']].map(([key,label])=>`<button type="button" data-action="condition" data-condition="${key}" aria-pressed="${(catalogFilters.condition||'all')===key}">${label}</button>`).join('')}</div>`;}
function catalog(category='',isSearch=false,newWithTags=false){const parent=parentCategory(category)?.name||'';if(categoryScope!==parent){categoryScope=parent;catalogFilters.categories=category&&category!==parent?[category]:[];} if(newWithTags)catalogFilters.condition='new';const filters={...catalogFilters};let products=filterProducts(catalogProducts(),{...filters,category:parent,search,brandCatalog:brands});if(sort==='asc')products.sort((a,b)=>a.price-b.price);if(sort==='desc')products.sort((a,b)=>b.price-a.price);const chosen=filterChips(filters,parent,brands);return `<div class="wrap catalog-page"><div class="page-head"><p class="eyebrow">VERA PRIVÉ / КАТАЛОГ</p><h1>Найдите свою вещь</h1>${shopSearch()}</div>${catalogFilterBar(state.products,{...filters,category:parent},esc,brands)}<div class="catalog-toolbar"><span class="small muted">Найдено: ${products.length}</span>${sortView(sort)}</div>${chosen.length?`<div class="applied-filters">${chosen.map(([key,value,label])=>`<button type="button" data-action="remove-filter" data-filter="${key}" data-value="${esc(value)}" aria-label="Удалить фильтр: ${esc(label)}">${esc(label)} ×</button>`).join('')}<button type="button" class="text-link" data-action="reset-filters">Сбросить всё ×</button></div>`:''}<div class="catalog-layout catalog-filtered-layout"><div class="catalog-results">${products.length?`<div class="product-grid">${products.map(productCard).join('')}</div>`:empty('Ничего не нашлось','Измените запрос или сбросьте фильтры.','/catalog','Все категории')}</div></div></div>`;}

function product(id){const p=catalogProducts().find(p=>p.id===id);if(p?.demo)return `<div class="wrap"><div class="page-head"><a class="text-link" href="#/catalog">← Каталог</a><h1>${esc(p.name)}</h1><p>${esc(p.description)}</p><strong>Тест генерации · не продаётся</strong></div>${gallery(p,esc,true)}</div>`;if(!p||p.approval==='pending'||p.archivedAt||p.approval==='archived')return `<div class="wrap">${empty('Товар не найден','Возможно, он больше не доступен.')}</div>`;return `<div class="wrap"><div class="page-head"><a class="eyebrow" href="#/catalog">КАТАЛОГ / ${esc(p.category)}</a></div><div class="split">${gallery(p,esc,true)}<div class="details-copy"><span class="eyebrow">VERA PRIVÉ · SELECTED</span><h1>${esc(p.name)}</h1><p class="price">${priceMarkup(p)}</p>${p.newWithTags?'<span class="condition-badge">Новое с биркой</span>':''}<p class="small muted">Цвет: ${esc(p.color)}</p><p class="description">${esc(p.description)}</p><p class="small">Размер <span class="muted">· выберите свой</span></p><div class="sizes">${p.sizes.map(s=>`<button class="size ${selectedSize===s?'selected':''}" data-action="size" data-size="${esc(s)}" aria-pressed="${selectedSize===s}">${esc(s)}</button>`).join('')}</div><button class="btn wide" data-action="add" data-id="${p.id}" ${p.stock<1?'disabled':''}>${p.stock?'Добавить в корзину':'Нет в наличии'} ${icon('bag')}</button><p class="small muted" style="margin-top:12px">${p.stock} шт. в наличии · общий остаток по всем размерам в демо</p><hr class="divider"><p class="small muted">Товар и характеристики демонстрационные. Условия доставки и оплаты будут доступны перед запуском магазина.</p><a class="text-link" style="display:inline-block;margin-top:20px" href="#/contact">Задать вопрос о товаре ↗</a>${returnNotice}</div></div></div>`;}
function cart(){return `<div class="wrap"><div class="page-head"><span class="eyebrow">ВАШ ВЫБОР</span><h1>Корзина</h1></div>${!state.cart.length?empty('Пока здесь тихо','Найдите вещь, которая станет частью вашей истории.'): `<div class="split"><div>${state.cart.map(r=>{const p=state.products.find(p=>p.id===r.id)||{name:"Товар недоступен",image:"/assets/vera-prive-logo.jpg",price:0,color:"",id:r.id};return `<div class="cart-row"><img src="${esc(p.image)}" alt="${esc(p.name)}"><div><h4><a href="#/product/${p.id}">${esc(p.name)}</a></h4><p class="small muted">${esc(p.color)} · ${esc(r.size)}</p><div class="quantity"><button data-action="quantity" data-id="${r.id}" data-size="${esc(r.size)}" data-delta="-1" aria-label="Уменьшить количество">−</button><span>${r.quantity}</span><button data-action="quantity" data-id="${r.id}" data-size="${esc(r.size)}" data-delta="1" aria-label="Увеличить количество">+</button></div></div><div class="cart-end">${money(p.price*r.quantity)}<button data-action="remove" data-id="${r.id}" data-size="${esc(r.size)}">Удалить</button></div></div>`;}).join('')}</div><aside class="panel"><h3>Ваш заказ</h3><div class="line-item"><span>Товары</span><span>${money(cartTotal(state))}</span></div><div class="line-item"><span>Доставка</span><span>Не рассчитана</span></div><div class="line-item total"><span>Итого за товары</span><span>${money(cartTotal(state))}</span></div><button class="btn wide" data-action="checkout">Оформить демо-заказ →</button><p class="small muted" style="margin-top:15px">Оплата не подключена. Демо-заказ не списывает деньги и не отправляется в магазин.</p></aside></div>`}</div>`;}
function orderCard(o,admin=false,supplier=null){const items=o.items.filter(i=>!supplier||i.supplier===supplier);return `<article class="order-card"><div class="order-top"><div><strong>${o.id}</strong><p class="small muted">${date(o.date)}</p></div>${status(o)}</div>${admin&&o.buyer?`<p class="small muted">Покупатель: ${esc(o.buyer.name)} · ${esc(o.buyer.email)}</p>`:''}${!supplier?deliverySummary(o.delivery,esc):''}${items.map(i=>`<div class="order-item"><span>${esc(i.name)} <small>· ${esc(i.size)} × ${i.quantity}</small></span><span>${money(i.price*i.quantity)}</span></div>`).join('')}<hr class="divider"><div class="line-item"><span>${supplier?'Сумма ваших товаров':'Стоимость товаров'}</span><strong>${money(items.reduce((a,i)=>a+i.price*i.quantity,0))}</strong></div>${admin&&o.status==='pending'?`<div class="order-actions"><button class="btn" data-action="confirm" data-id="${o.id}">Подтвердить демо-продажу</button><button class="btn light" data-action="cancel" data-id="${o.id}">Отменить</button></div>`:''}</article>`;}
function account(){if(identity.user){accountData(state).name=identity.user.name;accountData(state).email=identity.user.email;}const personalState=identity.server&&identity.user?.role==='admin'?{...state,orders:state.orders.filter(o=>o.userId===identity.user.id)}:state;const html=accountView(personalState,{esc,productCard,orderCard,empty,settings:sessionView()},route().split('/')[2]||'overview');return identity.user?html.replace('Используйте вымышленные данные для проверки интерфейса. Они сохраняются только в этом браузере.','Имя сохраняется в аккаунте. Для изменения почты подтвердите новый адрес кодом.').replace('Регистрация и вход будут подключены к серверу магазина. Сейчас это демо-профиль, доступный только на этом устройстве.','Изменения профиля доступны после повторного входа на другом устройстве.').replace('Демо-кабинет · без регистрации и реальной оплаты. Данные хранятся в этом браузере.','Заказы, адреса и избранное сохраняются в вашем аккаунте.'):html;}
const stat=(label,value,hint)=>`<div class="stat"><div><span>${label}</span><div class="value">${value}</div></div>${hint?`<span>${hint}</span>`:''}</div>`;
function workspace(content,section='overview',supplier=false){const menu=supplier?[['supplier','Обзор'],['supplier/products','Мои товары'],['supplier/payments','Продажи и выплаты']]:[['admin','Обзор'],['admin/brands','Бренды'],['admin/products','Товары'],['admin/archive','Архив'],['admin/orders','Заказы'],['admin/analytics','Аналитика'],['admin/suppliers','Поставщики']];return `<div class="wrap"><div class="workspace"><aside class="sidebar"><p class="eyebrow">${supplier?'ПАРТНЁРСКИЙ КАБИНЕТ':'УПРАВЛЕНИЕ МАГАЗИНОМ'}</p>${menu.map(([url,title])=>`<a class="${route()==='/'+url?'active':''}" href="#/${url}">${title}</a>`).join('')}<a href="#/account/settings">Настройки аккаунта</a><div class="sidebar-bottom">VERA PRIVÉ<br>Всё важное — в деталях.<br><br><a href="#/">← В магазин</a></div></aside><div class="workspace-content">${notice}<div data-photo-drafts></div><p class="photo-credits small" data-photo-credits role="status">Проверяем баланс кредитов…</p>${content}</div></div></div>`;}
function productTable(products,edit=false){const partner=route().startsWith('/supplier');return `<div class="table-wrap"><table><thead><tr><th>Товар</th><th>Цена</th><th>Остаток</th><th>Статус</th>${edit?'<th></th>':''}</tr></thead><tbody>${products.map(p=>`<tr><td><div class="table-product"><img src="${esc(p.image)}" alt=""><div>${p.archivedAt?`<span>${esc(p.name)}</span>`:`<a href="#/product/${p.id}">${esc(p.name)}</a>`}<div class="small muted">${esc(p.category)} · ${esc(supplierName(p.supplier))}</div></div></div></td><td>${p.price?priceMarkup(p):'Назначит магазин'}${!partner&&!p.archivedAt?`<br><button class="table-btn" data-action="discount" data-id="${p.id}">${p.discount?'Изменить скидку':'Сделать скидку'}</button>`:''}</td><td>${p.stock} шт.</td><td>${p.archivedAt?'В архиве':p.approval==='pending'?'На проверке':p.stock?'В продаже':'Продано'}</td>${edit&&!p.archivedAt?`<td><button class="table-btn" data-action="edit-product" data-id="${p.id}">${!partner&&p.approval==='pending'?'Проверить и одобрить':'Изменить'}</button></td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function productSearchView(products){return `<label>Поиск по названию или бренду<input id="workspace-product-search" type="search" value="${esc(workspaceQuery)}" placeholder="Название товара или бренд"></label><div id="workspace-product-results">${productTable(searchProducts(products,workspaceQuery,brands),true)}</div>`;}

function calculator(){return `<div class="calc"><div><p class="eyebrow">ПРОЗРАЧНЫЕ УСЛОВИЯ</p><h3>Как считается продажа</h3><label>Цена продажи, ₽<input id="calc-price" type="number" min="0" step="0.01" value="10000"></label><p class="formula">Количество: 1 · начисление после подтверждения продажи</p></div><div class="calc-result" id="calc-result">${calculation(1000000)}</div></div>`;}
function calculation(cents){const commission=Math.round(cents*.15);return `<div class="line-item"><span>Цена продажи</span><strong>${money(cents)}</strong></div><div class="line-item"><span>Комиссия Vera Privé · 15%</span><span>${money(commission)}</span></div><div class="line-item total"><span>Поставщику · 85%</span><strong>${money(cents-commission)}</strong></div><p class="formula">Остаток к выплате = начислено − фактические выплаты. Доставка в расчёт не включена.</p>`;}
function admin(section){if(section==='analytics')return workspace(analyticsView(state,analyticsSelection,esc),'analytics');if(section==='archive')return workspace('<h1>Архив</h1><p class="small muted">Товары удалённых поставщиков скрыты из каталога. История продаж и выплат сохранена.</p>'+productTable(state.products.filter(p=>p.archivedAt))+'<h3>Удалённые поставщики</h3>'+state.suppliers.filter(p=>p.deletedAt).map(p=>`<p><a class="text-link" href="#/admin/supplier/${p.id}">${esc(p.name)} →</a></p>`).join(''),'archive');if(section==='supplier'){const id=route().split('/')[3],partner=state.suppliers.find(p=>p.id===id);if(!partner)return workspace('<p>Поставщик не найден.</p>');const total=summary(state,id);return workspace(`<a href="#/admin/suppliers">← Все поставщики</a><h1>${esc(partner.name)}</h1><p class="supplier-contact small muted">${esc(partner.email||'Email ещё не указан')}${partner.deletedAt?' · Поставщик удалён':''}</p><div class="stats">${stat('Долг Vera Privé',money(total.balance))}${stat('Выплачено',money(total.paid))}</div><button class="btn" data-action="payout" data-id="${esc(id)}" ${total.balance<=0?'disabled':''}>Записать выплату</button>${identity.server&&!partner.deletedAt?`<button class="btn light" data-action="invite-supplier" data-id="${esc(id)}">Приглашения и доступ</button>`:''}${!partner.deletedAt?`<button class="btn light supplier-delete" data-action="delete-supplier" data-id="${esc(id)}">Удалить поставщика</button>`:''}<h3>Все товары поставщика</h3>${productSearchView(state.products.filter(p=>p.supplier===id))}${paymentHistory(state,id,esc,true)}`);}if(section==='brands')return workspace(brandLoadError?'<p class="form-error">'+esc(brandLoadError)+'</p>':brandAdminView(brands,esc),'brands');const s=summary(state);let content='';if(section==='products'){content=`<div class="section-head"><div><p class="eyebrow">АССОРТИМЕНТ</p><h1>Товары</h1></div><button class="btn" data-action="new-product">+ Добавить товар</button></div>${productSearchView(state.products.filter(p=>!p.archivedAt))}`;}else if(section==='orders'){content=`<h1>Заказы</h1><p class="muted small" style="margin-top:15px">Подтверждение продажи списывает остаток и начисляет комиссию. Это не подтверждение банковского платежа.</p>${state.orders.length?state.orders.map(o=>orderCard(o,true)).join(''):empty('Новых заказов пока нет','Оформите демо-заказ в каталоге, чтобы проверить расчёты.')}`;}else if(section==='suppliers'){content=`<div class="section-head"><h1>Поставщики</h1><button class="btn" data-action="new-supplier">+ Поставщик</button></div><label>Поиск поставщика<input id="supplier-list-search" type="search" placeholder="Имя или название"></label><div id="supplier-list">${state.suppliers.filter(p=>!p.deletedAt).map(p=>{const t=summary(state,p.id);return `<article class="order-card" data-supplier-name="${esc(p.name.toLowerCase())}"><div class="order-top"><h3><a href="#/admin/supplier/${p.id}">${esc(p.name)} ↗</a></h3><button class="btn light" data-action="payout" data-id="${p.id}" ${t.balance<=0?'disabled':''}>Записать выплату</button></div><div class="line-item"><span>Начислено (85%)</span><strong>${money(t.due)}</strong></div><div class="line-item"><span>Выплачено</span><span>${money(t.paid)}</span></div><div class="line-item total"><span>Остаток к выплате</span><strong>${money(t.balance)}</strong></div></article>`;}).join('')}</div>`;}else{content=`<p class="eyebrow">VERA PRIVÉ · ОБЗОР</p><h1 style="margin-top:12px">Магазин в деталях</h1><div class="stats">${stat('Подтверждённые продажи',money(s.revenue),`${s.sold} шт.`)}${stat('Комиссия магазина',money(s.commission),'15% от продаж')}${stat('К выплате поставщикам',money(s.balance),'После выплат')}</div><div class="section-head"><h3>Последние заявки</h3><a class="text-link" href="#/admin/orders">Все заказы →</a></div>${state.orders.length?state.orders.slice(0,2).map(o=>orderCard(o,true)).join(''):'<p class="muted small">Пока заявок нет. Создайте демо-заказ в витрине — он появится здесь.</p>'}<a class="btn light" href="#/admin/analytics">Открыть аналитику →</a>`;}return workspace(content,section);}
let supplierId=identity.server?identity.user?.supplierId:'s1';
function supplier(section){if(!supplierId)return workspace('<p>Аккаунт не привязан к поставщику. Обратитесь к администратору.</p>',section,true);const s=summary(state,supplierId);const selector=`<div class="section-head"><div><p class="eyebrow">ЛИЧНЫЙ КАБИНЕТ ПОСТАВЩИКА</p><h1>${esc(supplierName(supplierId))}</h1></div></div>`;let content=selector+supplierNotifications(state,supplierId,esc);if(section==='products')content+='<div class="section-head"><h3>Мои товары</h3><button class="btn" data-action="new-product">+ Добавить товар</button></div>'+productSearchView(state.products.filter(p=>p.supplier===supplierId));else if(section==='payments'){content+=`<div class="stats">${stat('Начислено',money(s.due))}${stat('Выплачено',money(s.paid))}${stat('Долг Vera Privé',money(s.balance))}</div><h3>Продажи</h3>${state.orders.filter(o=>o.status==='sold'&&o.items.some(i=>i.supplier===supplierId)).map(o=>orderCard(o,false,supplierId)).join('')||'<p class="small muted" style="margin:20px 0">Подтверждённых продаж пока нет.</p>'}${paymentHistory(state,supplierId,esc)}`;}else content+=`<div class="stats">${stat('Продано вещей',s.sold+' шт.')}${stat('Начислено вам',money(s.due),'85% от продаж')}${stat('Долг Vera Privé',money(s.balance))}</div>${calculator()}<div class="section-head"><h3>Ваши товары</h3><a class="text-link" href="#/supplier/products">Все товары →</a></div>${productTable(state.products.filter(p=>p.supplier===supplierId))}`;return workspace(content,section,true);}
function information(contact){return `<div class="wrap"><div class="page-head"><p class="eyebrow">VERA PRIVÉ</p><h1>${contact?'Мы рядом':'Вещи с вашим характером'}</h1></div><div class="contact-block">${contact?'<h3>Связаться с магазином</h3><p>По вопросам магазина и персональных данных: <a href="mailto:info@shop.example.com">info@shop.example.com</a> · <a href="tel:+70000000000">+7 (000) 000-00-00</a> · <a href="https://t.me/example_shop_contact" target="_blank" rel="noopener noreferrer">Telegram @example_shop_contact</a>. Доставка: Достависта, Яндекс Доставка, СДЭК, Почта России и другие курьеры по согласованию. Самовывоз: Москва, метро Примерная, улица Примерная; точный адрес и время согласовываются при подтверждении заказа.</p><div class="notice">Магазин готовится к запуску. Сообщения и платежи в этой версии не отправляются.</div>':'<p>Vera Privé — пространство одежды и аксессуаров, которые легко становятся частью вашего гардероба. Спокойные цвета, выразительные детали и сочетания, в которых комфортно быть собой.</p><p>Сейчас вы видите первую версию магазина. Ассортимент, фотографии и характеристики демонстрационные. Условия оплаты, доставки и возврата появятся перед запуском.</p>'}<a class="btn light" href="#/catalog">Открыть коллекцию →</a></div></div>`;}
function render(){rememberInvitation();const r=route();const parts=r.split('/').filter(Boolean);let html;const gate=authGate(parts[0]);if(stateLoadError)html='<div class="wrap"><div class="empty"><h2>Не удалось загрузить магазин</h2><p>'+esc(stateLoadError)+'</p><button class="btn" onclick="location.reload()">Повторить</button></div></div>';else if(parts[0]==='invite')html=invitationView(identity.user,esc);else if(gate)html=gate;else if(parts[0]==='auth')html=authView(parts[1]);else if(!parts.length)html=home();else if(parts[0]==='new-with-tags')html=catalog('',false,true);else if(parts[0]==='catalog'||parts[0]==='search')html=catalog(parts[1],parts[0]==='search');else if(parts[0]==='product')html=product(parts[1]);else if(parts[0]==='cart')html=cart();else if(parts[0]==='checkout')html=identity.server&&!identity.user?authView('login'):checkoutPage(state,esc,{name:identity.user?.name||accountData(state).name,demo:!identity.server});else if(parts[0]==='account')html=(['admin','supplier'].includes(identity.user?.role)?'<div class="wrap"><p class="photo-credits small" data-photo-credits role="status">Проверяем баланс кредитов…</p></div>':'')+account();else if(parts[0]==='cookies')html=cookieInformation();else if(parts[0]==='favorites')html=favoritesPage();else if(parts[0]==='admin')html=admin(parts[1]);else if(parts[0]==='supplier')html=supplier(parts[1]);else if(parts[0]==='about'||parts[0]==='contact'){html=information(parts[0]==='contact');if(parts[0]==='about')html=html.replace('<div class="contact-block">','<div class="contact-block"><img class="brand-full" src="/assets/vera-prive-logo.jpg" alt="Vera Privé — Vintage & Luxury">');}else html=`<div class="wrap">${empty('Страница не найдена','Вернитесь в каталог.')}</div>`;app.innerHTML=header()+`<main id="main">${identity.server?liveCopy(html):html}</main>`+footer();syncHeader();bindCheckout(app.querySelector('#checkout-form'),state);refreshPhotoCredits(identity.user?.id||'anonymous');refreshPhotoDrafts(id=>productForm(undefined,id));bindCategoryFields(app);bindCategoryBrowser(app);markRequired(app);bindBrandPicker(app,brands,esc);bindBrandAdmin(app,brands,esc);searchSuggestions(app,brands,esc);bindGalleries(app);bindIdentity();mountCookieNotice();bindCatalogControls(app,value=>{sort=value;render();});if(!gate&&parts[0]==="supplier"&&(!parts[1]||parts[1]==="payments"))document.querySelector(".workspace-content")?.insertAdjacentHTML("beforeend",(identity.server?liveCopy(salesChart(state,parts[0]==="supplier"?supplierId:null,chartPeriod)):salesChart(state,parts[0]==="supplier"?supplierId:null,chartPeriod)));}
function openDialog(title,content){modal.innerHTML=`<div class="dialog-head"><h3>${title}</h3><button class="dialog-close" data-action="close" aria-label="Закрыть">×</button></div>${content}`;if(identity.server)modal.innerHTML=liveCopy(modal.innerHTML);modal.showModal();markRequired(modal);}
function brandForm(id){const b=findBrand(brands,id);openDialog(b?'Редактировать бренд':'Добавить бренд',`<form id="brand-form" data-id="${esc(b?.id||'')}"><label>Название<input name="name" maxlength="100" required value="${esc(b?.name||'')}"></label><label>Другие написания через запятую<input name="aliases" value="${esc(b?.aliases.join(', ')||'')}"></label><p class="small muted">Поиск понимает простую транслитерацию. Для особого произношения добавьте русское написание, например «Найк».</p><p class="form-error" role="alert"></p><button class="btn wide">Сохранить</button></form>`);}
async function productForm(id,draftId){let draft;try{if(draftId)draft=await draftRequest('/'+draftId);}catch(e){toast(e.message);return;}if(draft?.productId)id=draft.productId;const original=state.products.find(p=>p.id===id);if(id&&!original){toast('Товар недоступен.');return;}const f=draft?.fields;const p=f?{...original,id:original?.id,name:f.name,description:f.description,color:f.color,audience:f.audience,modelGender:f.modelGender,brandId:f.brand,category:f.category,sizes:f.sizes||[],newWithTags:!!f.newWithTags,stock:Number(f.stock||0),price:Number(f.price||0)*100,supplier:f.supplier,photoJobs:original?.photoJobs,photoStudio:original?.photoStudio}:original;const partner=route().startsWith('/supplier');assertProductAccess(original,partner?supplierId:null);openDialog(draft?'Черновик товара':p?'Редактировать товар':'Новая вещь в коллекции',`<form id="product-form" data-id="${p?.id||''}"><div class="form-grid"><label class="full">Название<input name="name" maxlength="150" required value="${esc(p?.name||'')}"></label>${productBrandInput(brands,p?.brandId,esc)}<label>Для кого<select name="audience" required><option value="">Выберите раздел</option>${Object.entries(audienceLabels).map(([key,label])=>`<option value="${key}" ${p?.audience===key?'selected':''}>${label}</option>`).join('')}</select></label>${categoryFields(p?.category,esc,true)}<label ${partner?'hidden':''}>Найти поставщика<input id="product-supplier-search" type="search" placeholder="Имя или название"></label><label>Поставщик<select name="supplier" required ${route().startsWith('/supplier')?'disabled':''}>${state.suppliers.filter(s=>!s.deletedAt).map(s=>`<option value="${s.id}" ${s.id===(p?.supplier||(route().startsWith('/supplier')?supplierId:null))?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label><label ${partner?'hidden':''}>Цена, ₽<input ${partner?'disabled':''} name="price" type="number" min="1" max="10000000" step="0.01" required value="${p?(p.originalPrice||p.price)/100:''}"></label><label>Остаток, шт.<input name="stock" type="number" min="0" max="100000" step="1" required value="${p?.stock??1}"></label><label>Цвет<input name="color" required maxlength="80" value="${esc(p?.color||'')}"></label>${sizeFields(p?.sizes||[],esc)}<label class="check-label full product-condition"><input type="checkbox" name="newWithTags" ${p?.newWithTags?'checked':''}> Новое с биркой</label><div class="full photo-editor"><label class="photo-upload">Загрузить фотографии *<input name="uploads" type="file" multiple accept="image/jpeg,image/png,image/webp"><span>JPEG, PNG или WebP · до 20 МБ. Фото уменьшаются автоматически.</span></label><p class="photo-total small muted"></p><div class="photo-preview"></div><details class="photo-links"><summary>Добавить фотографии по ссылке</summary><label>Каждая HTTPS-ссылка с новой строки<textarea name="photos">${esc(p?productImages(p).join("\n"):"")}</textarea></label></details></div><label class="full">Описание<textarea name="description" maxlength="2000" required>${esc(p?.description||'')}</textarea></label></div><p class="form-error" role="alert"></p><button class="btn wide" type="submit">${partner?'Отправить на проверку':p?.approval==='pending'?'Одобрить и опубликовать':p?'Сохранить изменения':'Добавить в каталог'}</button><p class="small muted" style="margin-top:12px">Товар сохраняется в демо-каталог этого браузера.</p></form>`);bindFixedPhotos(modal.querySelector('#product-form'),p,esc,draft).catch(e=>{modal.querySelector('.form-error').textContent=e.message;});bindProductFields(modal,brands,esc);const supplierSearch=modal.querySelector('#product-supplier-search');supplierSearch.addEventListener('input',()=>{const select=modal.querySelector('[name=supplier]'),selected=select.value;const rows=state.suppliers.filter(s=>!s.deletedAt&&(s.id===selected||s.name.toLowerCase().includes(supplierSearch.value.toLowerCase())));select.innerHTML=rows.map(s=>`<option value="${esc(s.id)}" ${s.id===selected?'selected':''}>${esc(s.name)}</option>`).join('');});}
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b)return;const {action,id,size,delta}=b.dataset;try{
  if(route().startsWith('/supplier')&&['new-brand','edit-brand','delete-brand','delete-brand-confirm','discount','confirm','cancel','new-supplier','delete-supplier','delete-supplier-confirm','payout','receipt'].includes(action))throw Error('Это действие доступно только администратору.');
  if(identity.server&&action==='verify-invite'){b.disabled=true;try{await verifyCurrentEmail();}finally{b.disabled=false;}return;}
  if(identity.server&&action==='invite-supplier'){await inviteDialog(id);return;}
  if(identity.server&&action==='accept-invite'){b.disabled=true;try{await invitationRequest('accept',{token:invitationToken()});clearInvitation();location.replace('/?invited=1#/auth/login');}finally{b.disabled=false;}return;}
  if(identity.server&&action==='revoke-invite'){b.disabled=true;await invitationRequest(id,null,'DELETE');await inviteDialog(b.dataset.supplier);return;}
  if(identity.server&&['favorite','add','quantity','remove','confirm','cancel','read-notifications','address-primary','address-delete-confirm'].includes(action)){
    if(!identity.user){location.hash='/auth/login';toast('Войдите, чтобы сохранить выбранное.');return;}
    if(b.dataset.busy)return;b.dataset.busy='1';b.disabled=true;
    const adding=!state.favorites.includes(id),rect=b.getBoundingClientRect();
    try{
      if(action==='favorite'){await command('favorite',{id});updateFavoriteControls(app,id,state.favorites);b.closest('.product')?.classList.toggle('removed-favorite',!adding&&route().includes('favorites'));if(adding)flyHeart(rect);else toast('Убрано из избранного');return;}
      if(action==='add'||action==='quantity'){if(action==='add'&&!selectedSize)throw Error('Сначала выберите размер.');await command('cart',{id,size:action==='add'?selectedSize:size,delta:action==='add'?1:Number(delta)});}
      if(action==='remove')await command('cart-remove',{id,size});
      if(action==='confirm'||action==='cancel')await command('order',{id,confirm:action==='confirm'});
      if(action==='read-notifications')await command('read-notifications');
      if(action==='address-primary')await command('address-primary',{id});
      if(action==='address-delete-confirm'){await command('address-delete',{id});modal.close();}
      render();return;
    }finally{delete b.dataset.busy;b.disabled=false;}
  }
  if(action==='read-notifications'){state.payouts.filter(p=>p.supplier===supplierId).forEach(p=>p.readAt=new Date().toISOString());save();render();return;}
  if(action==='receipt'){openDialog('Прикрепить чек',`<form id="receipt-form" data-id="${esc(id)}"><label>Чек<input name="receipt" type="file" accept="application/pdf,image/jpeg,image/png,image/webp" required></label><p class="small muted">До 2 МБ</p><p class="form-error" role="alert"></p><button class="btn">Сохранить чек</button></form>`);return;}
  if(action==='new-brand'||action==='edit-brand'){brandForm(id);return;}
  if(action==='delete-brand'){const brand=findBrand(brands,id);openDialog('Удалить бренд?',`<p>${esc(brand?.name)}</p><p class="small muted">Бренд исчезнет из списка выбора. Используемый в товарах бренд удалить нельзя.</p><p class="form-error" role="alert"></p><button class="btn" data-action="delete-brand-confirm" data-id="${esc(id)}">Удалить</button>`);return;}
  if(action==='delete-brand-confirm'){brands=await deleteBrand(brands,id,state.products,identity.server);modal.close();render();return;}
  if(action==='close'){await modal.querySelector('#product-form')?.flushPhotoDraft?.();modal.close();refreshPhotoDrafts(id=>productForm(undefined,id));return;}
  if(action==='gallery-prev'||action==='gallery-next'){moveGallery(b.closest('.gallery').querySelector('.gallery-track'),action==='gallery-next'?1:-1);return;}
  if(action==='subcategory'){const values=catalogFilters.categories||[];catalogFilters.categories=values.includes(b.dataset.category)?values.filter(c=>c!==b.dataset.category):[...values,b.dataset.category];const y=window.scrollY,query=document.querySelector('.category-find input')?.value||'';render();const input=document.querySelector('.category-find input');if(input&&query){input.value=query;input.dispatchEvent(new Event('input',{bubbles:true}));}window.scrollTo({top:y,behavior:'instant'});return;}
  if(action==='audience'){catalogFilters.audience=b.dataset.audience;const y=window.scrollY;render();document.querySelector(`[data-action=audience][data-audience="${catalogFilters.audience}"]`)?.focus({preventScroll:true});window.scrollTo({top:y,behavior:'instant'});return;}
  if(action==='condition'){catalogFilters.condition=b.dataset.condition;delete catalogFilters.newWithTags;if(route()==='/new-with-tags')location.hash='/catalog';else render();return;}
  if(action==='remove-filter'){catalogFilters=removeFilter(catalogFilters,b.dataset.filter,b.dataset.value);if(b.dataset.filter==='category'){categoryScope='';location.hash='/catalog';}else render();return;}
  if(action==='analytics-month'){analyticsSelection.month=b.dataset.month;render();return;}
  if(action==='reset-filters'){catalogFilters={min:'',max:'',sizes:[],sale:false};search='';if(route()!=='/catalog')location.hash='/catalog';else render();return;}
  if(action==='discount'){const p=state.products.find(p=>p.id===id);if(!p||(route().startsWith('/supplier')&&p.supplier!==supplierId))throw Error('Товар недоступен.');openDialog('Скидка на товар','<p>'+esc(p.name)+'</p><p class="small muted">Обычная цена: '+money(p.originalPrice||p.price)+'. Комиссия считается от цены со скидкой.</p><form id="discount-form" data-id="'+p.id+'"><label>Скидка, %<input name="discount" type="number" min="0" max="90" step="1" required value="'+(p.discount||0)+'"></label><p class="small muted">0% — отменить скидку. Ранее созданные заказы сохраняют прежнюю цену.</p><p class="form-error" role="alert"></p><button class="btn wide">Применить скидку</button></form>');return;}
  if(action==='address-new'||action==='address-edit'){openDialog(action==='address-new'?'Новый адрес':'Изменить адрес',addressForm(accountData(state).addresses.find(a=>a.id===id),esc));return;}
  if(action==='address-primary')primaryAddress(state,id);
  if(action==='address-delete'){openDialog('Удалить адрес?',`<p class="small muted">Адрес будет удалён из демонстрационного профиля.</p><div class="order-actions"><button class="btn" data-action="address-delete-confirm" data-id="${id}">Удалить</button><button class="btn light" data-action="close">Оставить</button></div>`);return;}
  if(action==='address-delete-confirm'){removeAddress(state,id);save();modal.close();render();toast('Адрес удалён');return;}
  if(action==='order-details'){const order=state.orders.find(o=>o.id===id);if(order)openDialog(`Заказ ${esc(order.id)}`,deliverySummary(order.delivery,esc)+orderDetails(order,esc));return;}
  if(action==='size'){selectedSize=size;render();return;}
  if(action==='favorite'){const adding=!state.favorites.includes(id),rect=b.getBoundingClientRect();state.favorites=adding?[...state.favorites,id]:state.favorites.filter(x=>x!==id);save();updateFavoriteControls(app,id,state.favorites);if(route()==='/favorites'||route()==='/account/favorites'){const card=b.closest('.product');card?.classList.toggle('removed-favorite',!adding);}if(adding)flyHeart(rect);else toast('Убрано из избранного');return;}
  if(action==='add'){if(!selectedSize)throw Error('Сначала выберите размер.');addToCart(state,id,selectedSize);toast('Вещь добавлена в корзину');}
  if(action==='quantity')addToCart(state,id,size,Number(delta));
  if(action==='remove')state.cart=state.cart.filter(r=>!(r.id===id&&r.size===size));
  if(action==='checkout'){location.hash='/checkout';return;}
  if(action==='confirm'||action==='cancel'){finishOrder(state,id,action==='confirm');toast(action==='confirm'?'Демо-продажа подтверждена. Начисления обновлены.':'Заявка отменена');}
  if(action==='new-product'||action==='edit-product'){productForm(id);return;}
  if(action==='delete-supplier'){const partner=state.suppliers.find(x=>x.id===id);if(!partner||partner.deletedAt)throw Error('Поставщик уже удалён.');openDialog('Удалить поставщика?',`<div class="supplier-dialog-intro"><p><strong>${esc(partner.name)}</strong></p><p class="small muted">Все его товары перейдут в архив и исчезнут из каталога. Доступ к кабинету и неиспользованные приглашения будут закрыты. Продажи, долг и чеки сохранятся. Заявки с архивными товарами нельзя будет подтвердить.</p></div><div class="order-actions"><button class="btn" data-action="delete-supplier-confirm" data-id="${esc(id)}">Удалить и архивировать</button><button class="btn light" data-action="close">Отмена</button></div>`);return;}
  if(action==='delete-supplier-confirm'){if(b.disabled)return;b.disabled=true;try{if(identity.server)await command('supplier-delete',{id});else{archiveSupplier(state,id);save();}modal.close();location.hash='/admin/suppliers';render();toast('Поставщик удалён. Товары в архиве.');}finally{b.disabled=false;}return;}
  if(action==='new-supplier'){openDialog('Добавить поставщика','<form id="supplier-form" class="supplier-dialog-form"><label>Имя или название<input name="name" required maxlength="100" autocomplete="organization"></label><label>Email поставщика<input name="email" type="email" required maxlength="150" autocomplete="email"></label><p class="form-error" role="alert"></p><button class="btn wide">Добавить</button></form>');return;}
  if(action==='payout'){openDialog('Записать выплату',`<p class="small muted">${esc(supplierName(id))} · доступно ${money(summary(state,id).balance)}</p><form id="payout-form" data-id="${id}"><label>Сумма фактической выплаты, ₽<input name="amount" required type="number" step="0.01" min="0.01" max="${summary(state,id).balance/100}"></label><label>Чек (необязательно)<input name="receipt" type="file" accept="application/pdf,image/jpeg,image/png,image/webp"></label><p class="small muted">PDF или изображение, до 2 МБ</p><p class="form-error" role="alert"></p><button class="btn wide">Записать демо-выплату</button><p class="small muted" style="margin-top:12px">Учётная запись, без перевода денег.</p></form>`);return;}
  save();render();
}catch(err){toast(err.message);}});
document.addEventListener('change',async e=>{
  if(e.target.id==='sort'){sort=e.target.value;render();}

  if(e.target.id?.startsWith('analytics-')){const key=e.target.id.slice(10);analyticsSelection[key]=e.target.value;render();return;}
  if(e.target.id==='chart-period'){chartPeriod=Number(e.target.value);render();}

});
document.addEventListener('input',e=>{if(e.target.id==='calc-price'){const value=Number(e.target.value);document.querySelector('#calc-result').innerHTML=Number.isFinite(value)&&value>=0&&value<=1e9?calculation(Math.round(value*100)):'<p class="form-error">Укажите цену от 0 до 1 000 000 000 ₽.</p>';}});
document.addEventListener('submit',async e=>{const f=e.target;if(!['checkout-form','search-form','catalog-filters','discount-form','profile-form','address-form','brand-form','product-form','supplier-form','payout-form','receipt-form','invite-form'].includes(f.id))return;e.preventDefault();if(f.dataset.saving||f.dataset.photoBusy)return;f.dataset.saving='1';const submit=f.querySelector('button[type=submit],button:not([type])');if(submit)submit.disabled=true;const data=new FormData(f);try{
  if(route().startsWith('/supplier')&&['brand-form','supplier-form','discount-form','payout-form','receipt-form'].includes(f.id))throw Error('Это действие доступно только администратору.');
  if(f.id==='checkout-form'){validateAddressSelection(f);const values=Object.fromEntries(data),body={method:values.method,recipient:values.recipient,phone:values.phone,addressId:values.addressId,address:values,remember:data.has('remember')};const delivery=prepareDelivery(state,body);if(identity.server)await command('checkout',body);else{const order=checkout(state);order.delivery=delivery;if(body.remember&&delivery.address)rememberAddress(state,delivery.address);save();}modal.close();location.hash='/account/orders';render();toast(identity.server?'Заказ передан в магазин. Оплата не списана.':'Демо-заказ создан');return;}
  if(f.id==='search-form'){search=String(data.get('search')).trim();homeLimit=12;if(route()==='/'||route()===''){render();document.querySelector('#home-finds')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});}else if(route()==='/search'||route().startsWith('/catalog'))render();else location.hash='/search';return;}
  if(f.id==='catalog-filters'){const v=Object.fromEntries(data);if(v.min&&v.max&&Number(v.min)>Number(v.max))throw Error('Цена «от» не должна превышать цену «до».');catalogFilters={...v,audience:String(data.get('audience')||''),categories:data.getAll('categories').filter(c=>categoryAllowed(c,String(data.get('audience')||''))),condition:String(data.get('condition')||'all'),brands:data.getAll('brands'),sizes:data.getAll('sizes'),sale:data.has('sale')};categoryScope=v.category||'';const next='/catalog'+(v.category?'/'+encodeURIComponent(v.category):'');if(location.hash.slice(1)!==next)location.hash=next;else{render();requestAnimationFrame(scrollToContent);}return;}
  if(identity.server&&f.id==='invite-form'){await invitationRequest('',{supplierId:f.dataset.id,email:data.get('email')});state=await commerceRequest();await inviteDialog(f.dataset.id);toast('Приглашение отправлено на почту');return;}
  if(f.id==='discount-form'&&identity.server)await command('discount',{id:f.dataset.id,percent:Number(data.get('discount'))});
  else if(f.id==='discount-form')setDiscount(state,f.dataset.id,Number(data.get('discount')),route().startsWith('/supplier')?supplierId:null);
  if(f.id==='profile-form'){const values=Object.fromEntries(data);if(identity.user)await saveAuthProfile(values);updateProfile(state,values);}
  if(f.id==='address-form'){if(identity.server)await command('address',{...Object.fromEntries(data),id:f.dataset.id||undefined});else saveAddress(state,Object.fromEntries(data),f.dataset.id||undefined);}
  if(f.id==='brand-form'){brands=await writeBrand(brands,{name:data.get('name'),aliases:data.get('aliases'),categories:findBrand(brands,f.dataset.id)?.categories||[]},f.dataset.id||undefined,identity.server);modal.close();render();toast('Бренд сохранён');return;}
  if(f.id==='product-form'){
    const photos=f.photoImages||[];if(photos.length<2||f.photoJobs&&!f.photoReady)throw Error('Дождитесь готовности всех трёх фото.');const image=photos[0];
    const price=Math.round(Number(data.get('price'))*100),stock=Number(data.get('stock')),sizes=data.getAll('sizes');
    const name=String(data.get('name')).trim(),description=String(data.get('description')).trim(),color=String(data.get('color')).trim();
    if(!name||!description||!color||!sizes.length||!Number.isSafeInteger(price)||(price<=0&&!route().startsWith('/supplier'))||price>1e9||!Number.isInteger(stock)||stock<0||stock>100000)throw Error('Проверьте название, описание, размеры, цену и остаток.');
    const brand=findBrand(brands,data.get('brand'));if(!brand){f.querySelector('[name=brand]').classList.add('field-invalid');throw Error('Выберите бренд из справочника.');}
    const previous=state.products.find(p=>p.id===f.dataset.id);if(route().startsWith('/supplier')&&previous&&previous.supplier!==supplierId)throw Error('Товар другого поставщика недоступен.');const p={id:f.dataset.id||'p'+crypto.randomUUID(),name,description,color,brandId:brand.id,brandName:brand.name,image,images:photos,price,stock,sizes,audience:String(data.get('audience')||''),newWithTags:data.has('newWithTags'),category:String(data.get('category')),supplier:route().startsWith('/supplier')?supplierId:String(data.get('supplier'))};if(previous?.photoPanels&&photos.every(src=>src.startsWith('/assets/test-coat.png#'))){p.photoPanels=true;p.photoLabels=photos.map(src=>({front:'Вид спереди',back:'Вид сзади',detail:'Ткань и детали'}[src.split('#')[1]]||'Деталь'));}if(previous?.discount){p.originalPrice=price;p.discount=previous.discount;p.price=Math.round(price*(100-p.discount)/100);}
    if(!allCategories.includes(p.category)){f.querySelector('[data-category-parent]').classList.add('field-invalid');throw Error('Выберите категорию.');}p.photoJobs=f.photoJobs;p.photoSettings=f.photoSettings;p.modelGender=f.photoModelGender;Object.assign(p,partnerProduct(previous,p,route().startsWith('/supplier')?supplierId:null));
    if(identity.server){await command('product',{...p,id:f.dataset.id||undefined,price});await f.clearPhotoDraft?.();modal.close();render();toast('Товар сохранён');return;}
    const index=state.products.findIndex(x=>x.id===p.id);if(!state.suppliers.some(s=>s.id===p.supplier))throw Error('Выберите поставщика.');if(index>=0)state.products[index]=p;else state.products.unshift(p);
  }
  if(f.id==='supplier-form'){const name=String(data.get('name')).trim();if(!name)throw Error('Укажите название.');if(state.suppliers.some(s=>s.name.toLowerCase()===name.toLowerCase()))throw Error('Такой поставщик уже есть.');const email=supplierEmail(data.get('email'));if(identity.server)await command('supplier',{name,email});else state.suppliers.push({id:'s'+crypto.randomUUID(),name,email});}
  if(f.id==='payout-form'){const receipt=await readReceipt(data.get('receipt'));if(identity.server)await command('payout',{supplier:f.dataset.id,amount:Math.round(Number(data.get('amount'))*100),receipt});else{payout(state,f.dataset.id,Math.round(Number(data.get('amount'))*100));Object.assign(state.payouts[0],{id:'pay-'+crypto.randomUUID(),receipt});}}
  if(f.id==='receipt-form'){const receipt=await readReceipt(data.get('receipt'));const payment=state.payouts.find(p=>p.id===f.dataset.id);if(!payment||!receipt)throw Error('Выберите чек для выплаты.');if(identity.server)await command('receipt',{id:f.dataset.id,receipt});else{payment.receipt=receipt;delete payment.readAt;}}
  save();modal.close();render();toast('Изменения сохранены');
}catch(err){const box=f.querySelector('.form-error');if(box)box.textContent=err.message;else toast(err.message);}finally{delete f.dataset.saving;if(submit)submit.disabled=false;}});
function scrollToContent(){if(route()==='/'){window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}const target=route().startsWith('/account/')?document.querySelector('#account-content'):document.querySelector('#main');if(target)target.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});}
document.addEventListener('click',e=>{const link=e.target.closest('a[href^="#"]');if(!link)return;if(link.getAttribute('href')==='#main'){e.preventDefault();document.querySelector('#main').scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});return;}if(link.hash===location.hash){e.preventDefault();scrollToContent();}});
if(new URLSearchParams(location.search).get('auth')==='reset')location.hash='/auth/reset';
let routeRequest=0;
window.addEventListener('hashchange',async()=>{const request=++routeRequest;if(identity.server){try{const latest=await commerceRequest();if(request!==routeRequest)return;state=latest;stateLoadError='';}catch(error){if(request!==routeRequest)return;stateLoadError=error.message;}}selectedSize='';if(modal.open)modal.close();render();requestAnimationFrame(scrollToContent);});
render();
document.addEventListener('input',event=>{
 if(event.target.id==='workspace-product-search'){workspaceQuery=event.target.value;const id=route().startsWith('/supplier')?supplierId:route().startsWith('/admin/supplier/')?route().split('/')[3]:null;document.querySelector('#workspace-product-results').innerHTML=productTable(searchProducts(state.products.filter(p=>(!id||p.supplier===id)&&(id||!p.archivedAt)),workspaceQuery,brands),true);}
 if(event.target.id==='supplier-list-search'){const query=event.target.value.toLowerCase().trim();document.querySelectorAll('[data-supplier-name]').forEach(row=>row.hidden=!row.dataset.supplierName.includes(query));}
});
document.addEventListener('click',event=>{const card=event.target.closest('[data-product-link]');if(card&&!event.target.closest('a,button,input')&&!card.querySelector('.gallery-track')?.dataset.dragged)location.hash='/product/'+card.dataset.productLink;});

function liveCopy(html){const replacements=[
 ['Товар сохраняется в демо-каталог этого браузера.','Товар сохраняется на сервере магазина. Товары поставщика публикуются после проверки администратором.'],
 ['Оформить демо-заказ','Отправить заявку'],['Создать демо-заказ','Отправить заявку'],['Подтвердить демо-продажу','Подтвердить продажу'],['Записать демо-выплату','Записать выплату'],
 ['Оплата не подключена. Демо-заказ не списывает деньги и не отправляется в магазин.','Заявка поступит администратору магазина. Онлайн-оплата пока не подключена.'],
 ['Это проверка сценария. Контакты не собираются, оплата не подключена, деньги не списываются.','Заявка будет передана магазину. Оплата не списывается. Доставку и оплату необходимо согласовать отдельно.'],
 ['Товар и характеристики демонстрационные. Условия доставки и оплаты будут доступны перед запуском магазина.','Условия доставки и оплаты уточняйте у магазина до подтверждения заказа.'],
 ['общий остаток по всем размерам в демо','общий остаток по всем размерам'],
 ['Для примерки сценария используйте вымышленный адрес. Доставка в демо не оформляется.','Сохранённые адреса доступны только в вашем аккаунте. Доставка согласовывается отдельно.'],
 ['Адрес будет удалён из демонстрационного профиля.','Адрес будет удалён из вашего профиля.'],['Добавить демо-адрес','Добавить адрес'],
 ['Пока заявок нет. Создайте демо-заказ в витрине — он появится здесь.','Новые заявки покупателей появятся здесь.'],['Оформите демо-заказ в каталоге, чтобы проверить расчёты.','Здесь появятся заявки покупателей.'],['первый демо-заказ','первый заказ'],['Демонстрационный профиль','Личный аккаунт'],['Данные демо-кабинета','Данные магазина'],['демо-продажи','продажи']
 ];for(const [from,to] of replacements)html=html.replaceAll(from,to);return html;}
async function inviteDialog(id){
 const rows=(await invitationRequest()).filter(x=>x.supplierId===id);
 if(modal.open)modal.close();
 openDialog('Доступ поставщика',`<div class="supplier-dialog-intro"><p class="supplier-dialog-name">${esc(supplierName(id))}</p><p class="small muted">Приглашение действует 7 дней. Поставщик входит со своей подтверждённой почтой.</p></div><form class="supplier-dialog-form" id="invite-form" data-id="${esc(id)}"><label>Email поставщика<input name="email" type="email" maxlength="150" required autocomplete="email" value="${esc(state.suppliers.find(x=>x.id===id)?.email||'')}"></label><p class="form-error" role="alert"></p><button class="btn wide">Отправить приглашение</button></form><div class="invite-list">${rows.map(x=>`<article class="order-card"><strong>${esc(x.email)}</strong><p class="small muted">${x.usedAt?'Принято':x.revokedAt?'Отозвано':x.expiresAt<Date.now()?'Истекло':'Действует до '+date(x.expiresAt)}</p>${!x.usedAt&&!x.revokedAt&&x.expiresAt>Date.now()?`<button class="text-link" data-action="revoke-invite" data-id="${esc(x.id)}" data-supplier="${esc(id)}">Отозвать приглашение</button>`:''}</article>`).join('')}</div>`);
}

modal.addEventListener('close',()=>{setTimeout(()=>refreshPhotoDrafts(id=>productForm(undefined,id)),500);});

bindSiteMenu({brand,brands:()=>brands,escape:esc,onCatalog:filters=>{search='';const category=filters.category||'';catalogFilters={min:'',max:'',sizes:[],categories:[],...filters};categoryScope=category;sort='new';const next='/catalog'+(category?'/'+encodeURIComponent(category):'');if(location.hash==='#'+next)render();else location.hash=next;},onSearch:query=>{search=query;catalogFilters={min:'',max:'',sizes:[],sale:false};if(location.hash==='#/search')render();else location.hash='/search';}});

document.addEventListener('input',event=>{
 const input=event.target.closest('[data-brand-search]');if(!input)return;
 const query=input.value.trim().toLocaleLowerCase('ru');
 const panel=input.parentElement;
 for(const item of panel.querySelectorAll('.filter-check,[data-menu-brand]'))item.hidden=!item.textContent.toLocaleLowerCase('ru').includes(query);
});
